# Practice Problems for ProbSpace: Probability & Calculus Tracks
# Auto-generated with 42 verified trilingual practice problems

def get_practice_problems():
    return [{'id': 'prob_101', 'difficulty': 'beginner', 'question': {'hy': 'Նետում ենք զառ: Ինչի՞ է հավասար կենտ թիվ բացվելու հավանականությունը:', 'en': 'A die is rolled. What is the probability of getting an odd number?', 'ru': 'Бросают кубик. Какова вероятность выпадения нечетного числа?'}, 'answer': '0.5', 'related_theory_id': 'theory-classical-prob', 'related_theory_hint': {'hy': 'Հիշեք հավանականության դասական բանաձևը՝ P = (Բարենպաստ ելքեր) / (Ընդհանուր ելքեր)։ Զառն ունի 6 նիստ, որոնցից քանի՞սն են կենտ:', 'en': 'Recall P = m/n. A die has 6 faces in total. How many of them are odd numbers?', 'ru': 'Вспомните формулу P = m/n. У кубика 6 граней. Сколько из них нечетные?'}, 'related_theory_solution': {'hy': 'Զառը նետելիս հնարավոր են 6 հավասարահնարավոր ելքեր՝ {1, 2, 3, 4, 5, 6}, այսինքն n=6։ Կենտ թվերն են 1, 3, 5, հետևաբար բարենպաստ ելքերի քանակը m=3։ Տեղադրելով դասական բանաձևի մեջ՝ P = m / n = 3 / 6 = 1/2 = 0.5։', 'en': 'There are n=6 total possible outcomes. The odd numbers are 1, 3, and 5, so m=3. P = m/n = 3/6 = 0.5.', 'ru': 'Всего 6 исходов (n=6). Нечетные это 1, 3, 5, их 3 (m=3). Следовательно, P = 3/6 = 0.5.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_102', 'difficulty': 'beginner', 'question': {'hy': '2 մետաղադրամ նետելիս, որքա՞ն է հավանականությունը, որ երկուսն էլ «Զինանշան» կլինեն:', 'en': 'Flip 2 coins. Prob of 2 Heads?', 'ru': '2 монеты. Вероятность 2-х орлов?'}, 'answer': '0.25', 'related_theory_id': 'theory-multiplication', 'related_theory_hint': {'hy': 'Մետաղադրամները իրարից անկախ են: Կիրառեք բազմապատկման թեորեմը կամ հաշվեք բոլոր հնարավոր 4 ելքերը:', 'en': 'The coin flips are independent. Use the multiplication theorem P(A∩B)=P(A)×P(B).', 'ru': 'Броски независимы. Используйте теорему умножения P(A∩B)=P(A)×P(B).'}, 'related_theory_solution': {'hy': 'Քանի որ մետաղադրամների նետումները անկախ են իրարից, յուրաքանչյուրի «Զինանշան» (Գերբ) ընկնելու հավանականությունը 1/2 է։ Երկուսի միաժամանակ զինանշան ընկնելու համար բազմապատկում ենք դրանք՝ 1/2 × 1/2 = 1/4 = 0.25։ Այլ կերպ՝ ընդհանուր ելքերն են ԳԳ, ԳԹ, ԹԳ, ԹԹ (4 ելք), մեզ պետք է 1-ը (ԳԳ), հավանականությունը՝ = 1/4:', 'en': 'Probability of Heads on one coin is 1/2. Since events are independent, 1/2 × 1/2 = 1/4 = 0.25.', 'ru': 'Вероятность орла на одной монете 1/2. События независимы, поэтому умножаем: 1/2 × 1/2 = 1/4 = 0.25.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_103', 'difficulty': 'beginner', 'question': {'hy': 'Քանի՞ եղանակով կարելի է դասավորել 5 տարբեր գիրք դարակում:', 'en': 'How many ways to arrange 5 different books on a shelf?', 'ru': 'Сколькими способами можно расставить 5 книг?'}, 'answer': '120', 'related_theory_id': 'theory-permutations', 'related_theory_hint': {'hy': 'Անհրաժեշտ է գտնել բոլոր առարկաների տեղափոխությունների քանակը։ Կիրառեք N-ի ֆակտորիալ բանաձևը (n!):', 'en': 'You need to find the number of permutations of 5 items. Use factorial (n!).', 'ru': 'Это задача на перестановки 5 элементов. Используйте факториал (n!).'}, 'related_theory_solution': {'hy': '5 տարբեր գրքեր դարակում շարելու եղանակների քանակը որոշվում է տեղափոխությունների բանաձևով՝ 5! (ֆակտորիալ)։<br>5! = 1 × 2 × 3 × 4 × 5 = 120։', 'en': 'The number of ways to arrange n distinct objects is n!. Here, 5! = 5 × 4 × 3 × 2 × 1 = 120.', 'ru': 'Количество перестановок из n элементов равно n!. Здесь 5! = 5 × 4 × 3 × 2 × 1 = 120.'}, 'track': 'probability', 'topic': 'combinatorics'}, {'id': 'prob_104', 'difficulty': 'beginner', 'question': {'hy': 'P(A)=0.7: Գտնել լրացուցիչ պատահույթի հավանականությունը:', 'en': 'P(A)=0.7. Find probability of the complement.', 'ru': 'P(A)=0.7. Найти вер. противоположного события.'}, 'answer': '0.3', 'related_theory_id': 'theory-axioms', 'related_theory_hint': {'hy': 'Իրադարձության և նրա միակ լրացուցիչ (հակադիր) իրադարձության հավանականությունների գումարը միշտ հավասար է 1-ի:', 'en': 'The sum of probabilities of an event and its complement always equals 1.', 'ru': 'Сумма вероятностей события и его дополнения всегда равна 1.'}, 'related_theory_solution': {'hy': 'Անդրեյ Կոլմոգորովի աքսիոմներից բխում է, որ լրացուցիչ իրադարձության հավանականությունը հավասար է 1 - P(A):<br>P(A-ի լրացուցիչ) = 1 - 0.7 = 0.3:', 'en': 'The complement formula is P(not A) = 1 - P(A). Thus, 1 - 0.7 = 0.3.', 'ru': 'Формула противоположного события: 1 - P(A). Следовательно, 1 - 0.7 = 0.3.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_201', 'difficulty': 'intermediate', 'question': {'hy': 'Արկղում կա 5 սպիտակ և 4 սև գնդիկ: Հանում են 2 գնդիկ: Որքա՞ն է հավանականությունը, որ երկուսն էլ սպիտակ են:', 'en': 'Urn: 5W, 4B. Draw 2. Prob both White?', 'ru': 'Урна: 5Б, 4Ч. Берем 2. Вероятность 2-х белых?'}, 'answer': '0.2778', 'related_theory_id': 'theory-combinations', 'related_theory_hint': {'hy': 'Կարող եք լուծել 2 եղանակով. կամ բազմապատկելով հավանականությունները առանց վերադարձի (5/9 * 4/8), կամ զուգորդությունների (Combinations) միջոցով:', 'en': 'Solve by multiplying probabilities without replacement (5/9 * 4/8) or using Combinations C(5,2)/C(9,2).', 'ru': 'Можно решить умножением вероятностей без возвращения (5/9 * 4/8) или через сочетания C(5,2)/C(9,2).'}, 'related_theory_solution': {'hy': 'Եղանակ 1 (պայմանական)՝ առաջինը սպիտակ լինելու հավանականությունը 5/9 է։ Երկրորդինը (երբ 1 սպիտակ արդեն հանվել է)՝ 4/8։ Բազմապատկում ենք՝ 5/9 × 4/8 = 20/72 = 5/18 ≈ 0.2778։<br>Եղանակ 2 (զուգորդություններ)՝ C(5,2) / C(9,2) = 10 / 36 = 5/18։', 'en': 'Method 1: (5/9) × (4/8) = 20/72 = 0.2778. Method 2: C(5,2) / C(9,2) = 10 / 36 = 5/18.', 'ru': 'Метод 1: (5/9) × (4/8) = 20/72 = 0.2778. Метод 2: C(5,2) / C(9,2) = 10 / 36 = 5/18.'}, 'track': 'probability', 'topic': 'combinatorics'}, {'id': 'prob_202', 'difficulty': 'intermediate', 'question': {'hy': '3 կրակոցից (p=0.4) գոնե մեկ անգամ կպնելու հավանականությունը:', 'en': '3 shots (p=0.4). Prob of at least 1 hit?', 'ru': '3 выстрела (p=0.4). Хотя бы 1 попадание?'}, 'answer': '0.784', 'related_theory_id': 'theory-binomial', 'related_theory_hint': {'hy': '«Գոնե մեկ» գտնելու ամենահեշտ ճանապարհը հակադիր իրադարձության միջոցով հաշվելն է. 1 - P(ոչ մի անգամ):', 'en': "The easiest way to find 'at least one' is using the complement: 1 - P(none).", 'ru': "Проще всего найти 'хотя бы одно' через противоположное событие: 1 - P(ни одного)."}, 'related_theory_solution': {'hy': 'Գոնե մեկ անգամ դիպչելու լրացուցիչ իրադարձությունն այն է, որ որսորդը ԲՈԼՈՐ 3 կրակոցների դեպքում վրիպի։ Վրիպելու հավանականությունը q = 1 - 0.4 = 0.6 է։ Երեք անգամ անընդմեջ վրիպելը՝ 0.6³ = 0.216։ Ուստի գոնե մեկ դիպչելը կլինի 1 - 0.216 = 0.784։', 'en': 'Miss probability is 1 - 0.4 = 0.6. Missing 3 times in a row is 0.6³ = 0.216. P(at least 1 hit) = 1 - 0.216 = 0.784.', 'ru': 'Вероятность промаха 1 - 0.4 = 0.6. Три промаха: 0.6³ = 0.216. В(хотя бы 1 попадание) = 1 - 0.216 = 0.784.'}, 'track': 'probability', 'topic': 'distributions'}, {'id': 'prob_203', 'difficulty': 'intermediate', 'question': {'hy': 'Զառը նետում ենք 2 անգամ: Որքա՞ն է հավանականությունը, որ գումարը 10 է:', 'en': 'Roll a die twice. Prob that sum is 10?', 'ru': 'Два броска кубика. Вероятность суммы 10?'}, 'answer': '0.0833', 'related_theory_id': 'theory-classical-prob', 'related_theory_hint': {'hy': 'Երկու զառի համար ընդհանուր ելքերի քանակը 36 է։ Քանի՞ զույգ կարող է տալ 10 գումար։', 'en': 'Total outcomes for 2 dice is 36. List the pairs that sum up to 10.', 'ru': 'У двух кубиков 36 исходов. Выпишите все пары, дающие сумму 10.'}, 'related_theory_solution': {'hy': 'Երկու զառ նետելիս հնարավոր ելքերի ընդհանուր քանակը 6 × 6 = 36 է։ Այն ելքերը, որոնց գումարը 10 է, հետևյալն են՝ (4,6), (5,5), և (6,4)։ Բարենպաստ ելքերի քանակը 3 է։ P = 3 / 36 = 1 / 12 ≈ 0.0833։', 'en': 'Total outcomes = 36. Favorable outcomes for sum of 10 are (4,6), (5,5), (6,4), which is 3. P = 3/36 = 1/12 ≈ 0.0833.', 'ru': 'Всего исходов 36. Благоприятных (сумма 10) три: (4,6), (5,5), (6,4). P = 3/36 = 1/12 ≈ 0.0833.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_301', 'difficulty': 'advanced', 'question': {'hy': 'X ~ N(0, 1): Գտնել P(|X| < 2) (մոտավոր, 2 նիշ):', 'en': 'X ~ N(0,1). Find P(|X| < 2).', 'ru': 'X ~ N(0,1). Найти P(|X| < 2).'}, 'answer': '0.95', 'related_theory_id': 'theory-normal', 'related_theory_hint': {'hy': 'Կիրառեք նորմալ բաշխման 68-95-99.7 էմպիրիկ կանոնը (երեք սիգմայի կանոն): Ի՞նչ է նշանակում |X| < 2:', 'en': 'Use the 68-95-99.7 empirical rule for Normal distribution. What does |X| < 2 mean?', 'ru': 'Используйте эмпирическое правило 68-95-99.7 (правило трех сигм). Что значит |X| < 2?'}, 'related_theory_solution': {'hy': 'Քանի որ X-ը ստանդարտ նորմալ բաշխում ունի (μ=0, σ=1), |X| < 2 նշանակում է X-ը գտնվում է միջինից 2σ հեռավորության վրա ([-2, 2] միջակայքում)։ Ըստ 68-95-99.7 կանոնի, տվյալների մոտ 95%-ը ընկնում է 2σ սահմաններում: P(|X| < 2) ≈ 0.95։', 'en': 'For a standard normal distribution (mean 0, std dev 1), the 68-95-99.7 rule states that ~95% of data falls within 2 standard deviations. So P(-2 < X < 2) ≈ 0.95.', 'ru': 'Для стандартного нормального распределения правило трех сигм гласит, что ~95% данных попадает в интервал 2σ. Значит, P(-2 < X < 2) ≈ 0.95.'}, 'track': 'probability', 'topic': 'distributions'}, {'id': 'prob_302', 'difficulty': 'advanced', 'question': {'hy': 'Հեռախոսակայան ստացվում է միջինում 2 զանգ րոպեում (Պուասոն)։ Գտեք 0 զանգ ստանալու հավանականությունը մեկ րոպեում:', 'en': 'Avg 2 calls/min (Poisson). Prob of 0 calls in a minute?', 'ru': 'В среднем 2 звонка в мин (Пуассон). Вер. 0 звонков?'}, 'answer': '0.1353', 'related_theory_id': 'theory-poisson', 'related_theory_hint': {'hy': 'Կիրառեք Պուասոնի բանաձևը՝ P(k) = (λ^k * e^-λ) / k! որտեղ λ-ն միջին արժեքն է, իսկ k-ն՝ զանգերի քանակը։', 'en': 'Use Poisson formula: P(k) = (λ^k * e^-λ) / k!. Here λ=2 and k=0.', 'ru': 'Формула Пуассона: P(k) = (λ^k * e^-λ) / k!. Здесь λ=2, k=0.'}, 'related_theory_solution': {'hy': 'Այստեղ միջինը (λ) = 2, իսկ մեզ հետաքրքրող քանակը (k) = 0։ Տեղադրելով Պուասոնի բանաձևի մեջ. P(0) = (2⁰ × e⁻²) / 0! = 1 × e⁻² / 1 = e⁻²։ Քանի որ e ≈ 2.718, e⁻² ≈ 0.1353:', 'en': 'Given λ = 2 events/min, we want k = 0 events. P(0) = (2^0 × e^-2) / 0! = e^-2 ≈ 0.1353.', 'ru': 'Дано λ = 2. Ищем P(0) = (2^0 × e^-2) / 0! = e^-2 ≈ 0.1353.'}, 'track': 'probability', 'topic': 'distributions'}, {'id': 'prob_305', 'difficulty': 'advanced', 'question': {'hy': 'Բայեսի խնդիր: հիվանդության հաճախականությունը 1% է: Թեստի ճշտությունը՝ 99%: Թեստը դրական է: Հավանականությունը, որ մարդը հիվանդ է?', 'en': 'Prevalence 1%. Test acc 99%. Test Positive. Prob diseased?', 'ru': 'Частота 1%. Тест 99%. Плюс. Болен?'}, 'answer': '0.5', 'related_theory_id': 'theory-bayes', 'related_theory_hint': {'hy': 'Զգուշացեք հայտնի տրամաբանական ծուղակից։ Թեստի արդյունքը և իրական հիվանդությունը նույնը չեն: Կիրառեք Բայեսի թեորեմը կամ Լրիվ հավանականության բանաձևը հայտարարում:', 'en': "Watch out for the base rate fallacy! Apply Bayes' Theorem properly.", 'ru': 'Не попадитесь в ловушку базового процента! Примените теорему Байеса.'}, 'related_theory_solution': {'hy': 'Դիցուք P(D)-ն հիվանդ լինելն է՝ 0.01։ P(+|D)-ն (դրական, երբ հիվանդ է) 0.99 է։ Առողջի (չհիվանդի) դեպքում P(H) = 0.99, իսկ թեստի սխալմամբ դրական ցույց տալու հավանականությունը (կեղծ դրական) P(+|H) = 0.01 է։<br>Բայեսով՝ P(D|+) = [0.01 × 0.99] / [0.01 × 0.99 + 0.99 × 0.01] = 0.0099 / 0.0198 = 0.5 (կամ 50%):<br>Ահա թե ինչու միայն մեկ թեստը բավարար չէ հազվադեպ հիվանդությունների համար:', 'en': 'P(Disease) = 0.01. P(Positive | Disease) = 0.99. P(Healthy) = 0.99. P(Positive | Healthy) = 0.01.<br>Bayes: (0.01 × 0.99) / (0.01 × 0.99 + 0.99 × 0.01) = 0.5.', 'ru': 'P(Болен) = 0.01. P(Тест+ | Болен) = 0.99. P(Здоров) = 0.99. P(Тест+ | Здоров) = 0.01.<br>Байес: (0.01 × 0.99) / (0.01 × 0.99 + 0.99 × 0.01) = 0.5.'}, 'track': 'probability', 'topic': 'bayes'}, {'id': 'prob_401', 'difficulty': 'olympic', 'question': {'hy': 'Բերտրանի պարադոքս․ Եթե պատահական լարը ընտրվում է ըստ միջնակետի դիրքի, որքա՞ն է հավանականությունը, որ այն երկար է ներգծած եռանկյունու կողմից:', 'en': 'Bertrand Paradox (midpoint method). Prob chord > triangle side?', 'ru': 'Парадокс Бертрана (метод середины).'}, 'answer': '0.25', 'related_theory_id': 'theory-rv-pdf', 'related_theory_hint': {'hy': 'Մտածեք «միջնակետի մեթոդի» մասին։ Որտե՞ղ պետք է գտնվի լարի միջնակետը, որպեսզի լարն ավելի երկար լինի, քան կանոնավոր եռանկյան կողմը: Դիտարկեք մակերեսների հարաբերությունը:', 'en': "Consider the 'midpoint method'. Where must the chord's midpoint lie? Think about the ratio of areas.", 'ru': "Подумайте о 'методе середины'. Где должна лежать середина хорды? Рассмотрите отношение площадей."}, 'related_theory_solution': {'hy': 'Եթե պատահականորեն ընտրում ենք կետ որպես լարի միջնակետ նախնական շրջանի ներսում, ապա լարը մեծ կլինի եռանկյան կողմից, եթե այդ միջնակետը գտնվի եռանկյանը ներգծած շրջանագծի ներսում։ Ներգծած շրջանագծի շառավիղը մեծ շրջանագծի շառավղի կեսն է (r = R/2)։ Մակերեսների հարաբերությունը՝ π(R/2)² / πR² = 1/4 = 0.25։', 'en': 'The midpoint must lie within the incircle of the triangle. The incircle has half the radius of the outer circle, so its area is 1/4th. Thus, P = 0.25.', 'ru': 'Середина хорды должна находиться внутри вписанной окружности. Радиус вписанной окружности вдвое меньше, поэтому её площадь составляет 1/4. P = 0.25.'}, 'track': 'probability', 'topic': 'random_variables'}, {'id': 'prob_402', 'difficulty': 'olympic', 'question': {'hy': 'E(X)=10: Չեբիշևով գտեք P(X > 20) վերին սահմանը, եթե Var(X)=5 (օգտագործեք միակողմանի տարբերակը կամ ստանդարտը):', 'en': 'E(X)=10, Var(X)=5. Chebyshev upper bound for P(X > 20)?', 'ru': 'E(X)=10, Var(X)=5. Граница Чебышёва для P(X > 20)?'}, 'answer': '0.05', 'related_theory_id': 'theory-chebyshev', 'related_theory_hint': {'hy': 'Կիրառեք Չեբիշևի անհավասարությունը՝ P(|X - μ| ≥ k) ≤ Var(X) / k²։ Ուշադրություն դարձրեք, որ կամայական բաշխման համար P(X - μ ≥ k) ≤ Var(X) / k² կարող է նաև օգտագործվել միակողմանի: Ստանդարտ մոտեցմամբ հաշվեք P(|X-10| ≥ 10)-ի արժեքը։', 'en': "Use Chebyshev's inequality P(|X - μ| ≥ k) ≤ Var(X) / k². Here μ=10, k=10.", 'ru': 'Используйте неравенство Чебышёва P(|X - μ| ≥ k) ≤ Var(X) / k². Здесь μ=10, k=10.'}, 'related_theory_solution': {'hy': 'Ըստ Չեբիշևի անհավասարության. P(|X - μ| ≥ k) ≤ Var(X) / k²։ Մեզ տրված է E(X) = μ = 10, Var(X) = 5։ Որպեսզի X > 20, պետք է շեղումը միջինից լինի գոնե k = 10։<br>P(|X - 10| ≥ 10) ≤ 5 / 10² = 5 / 100 = 0.05։', 'en': 'Chebyshev states P(|X - μ| ≥ k) ≤ Var(X)/k². With μ=10, Var(X)=5, and k=10: P(|X-10|>10) ≤ 5/100 = 0.05.', 'ru': 'Неравенство Чебышёва: P(|X - μ| ≥ k) ≤ Var(X)/k². При μ=10, Var(X)=5, и k=10: P(|X-10|>10) ≤ 5/100 = 0.05.'}, 'track': 'probability', 'topic': 'random_variables'}, {'id': 'prob_110', 'difficulty': 'beginner', 'question': {'hy': 'Տրված են P(A)=0.3, P(B)=0.2 և P(A∩B)=0.1: Գտնել P(A∪B):', 'en': 'Given P(A)=0.3, P(B)=0.2 and P(A∩B)=0.1. Find P(A∪B).', 'ru': 'Дано P(A)=0.3, P(B)=0.2 и P(A∩B)=0.1. Найти P(A∪B).'}, 'answer': '0.4', 'related_theory_id': 'theory-addition', 'related_theory_hint': {'hy': 'Կիրառեք հավանականությունների գումարման թեորեմը համատեղելի պատահույթների համար։ P(A∪B) = P(A) + P(B) - ?', 'en': 'Use the Addition Rule for non-mutually exclusive events: P(A∪B) = P(A) + P(B) - P(A∩B).', 'ru': 'Используйте теорему сложения для совместных событий: P(A∪B) = P(A) + P(B) - P(A∩B).'}, 'related_theory_solution': {'hy': 'Համատեղելի իրադարձությունների գումարման բանաձևն է՝ P(A∪B) = P(A) + P(B) - P(A∩B)։ Տեղադրելով թվերը կստանանք՝ 0.3 + 0.2 - 0.1 = 0.4։', 'en': 'Using the inclusion-exclusion principle for probabilities: P(A∪B) = P(A) + P(B) - P(A∩B) = 0.3 + 0.2 - 0.1 = 0.4.', 'ru': 'Принцип включения-исключения: P(A∪B) = P(A) + P(B) - P(A∩B) = 0.3 + 0.2 - 0.1 = 0.4.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_111', 'difficulty': 'beginner', 'question': {'hy': '52 թղթախաղից ընտրում ենք մեկ քարտ: Որքա՞ն է հավանականությունը, որ այն կլինի կարմիր կամ թագավոր:', 'en': "Draw one card from a 52-card deck. What is the probability it's either red or a king?", 'ru': 'Из колоды в 52 карты вынимают одну. Какова вероятность, что это красная карта или король?'}, 'answer': '0.5385', 'related_theory_id': 'theory-addition', 'related_theory_hint': {'hy': 'Քանի՞ կարմիր քարտ կա: Քանի՞ թագավոր կա: Ուշադրություն դարձրեք, որ կան կարմիր թագավորներ՝ մի հաշվեք դրանք կրկնակի:', 'en': "How many red cards? How many kings? Don't double-count the red kings!", 'ru': 'Сколько красных карт? Сколько королей? Не считайте красных королей дважды!'}, 'related_theory_solution': {'hy': 'Կա 26 կարմիր քարտ և 4 թագավոր։ Նրանցից 2-ը համ կարմիր են, համ թագավոր (կարմիր թագավորներ)։ Ըստ գումարման բանաձևի՝ 26/52 + 4/52 - 2/52 = 28/52 ≈ 0.5385։', 'en': 'There are 26 red cards and 4 kings. 2 of those kings are red. P(Red U King) = 26/52 + 4/52 - 2/52 = 28/52 = 7/13 ≈ 0.5385.', 'ru': '26 красных карт и 4 короля. Из них 2 — красные короли. P(Кр U Король) = 26/52 + 4/52 - 2/52 = 28/52 ≈ 0.5385.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_210', 'difficulty': 'intermediate', 'question': {'hy': 'Նետում ենք երկու կանոնավոր քառանիստ զառ (նիստերը՝ 1,2,3,4): Որքա՞ն է հավանականությունը, որ բացված թվերի գումարը կլինի 5:', 'en': 'Roll two regular tetrahedral dice (faces 1,2,3,4). What is the probability the sum is 5?', 'ru': 'Бросают два правильных тетраэдрических кубика (грани 1,2,3,4). Какова вероятность, что сумма выпавших очков равна 5?'}, 'answer': '0.25', 'related_theory_id': 'theory-classical-prob', 'related_theory_hint': {'hy': 'Հաշվեք բոլոր հնարավոր ելքերի քանակը (համարեք, որ զառերը 4 նիստանի են), որից հետո գտեք այն զույգերը, որոնց գումարը 5 է:', 'en': 'Find the total number of outcomes for two 4-sided dice. Then find how many pairs sum to 5.', 'ru': 'Найдите общее число исходов для двух 4-гранных кубиков. Затем найдите пары, дающие в сумме 5.'}, 'related_theory_solution': {'hy': 'Քառանիստ զառի նետման դեպքում յուրաքանչյուր զառ ունի 4 հնարավոր ելք։ Երկու զառերի համար՝ 4 × 4 = 16 ընդհանուր ելք: 5 գումար տվող զույգերն են՝ (1,4), (2,3), (3,2), (4,1)՝ ընդամենը 4 բարենպաստ ելք։ P = 4 / 16 = 1/4 = 0.25։', 'en': 'Total outcomes for two 4-sided dice = 4 × 4 = 16. Favorable outcomes: (1,4), (2,3), (3,2), (4,1) -> 4 pairs. P = 4/16 = 0.25.', 'ru': 'Всего исходов: 4 × 4 = 16. Благоприятные: (1,4), (2,3), (3,2), (4,1) — 4 пары. P = 4/16 = 0.25.'}, 'track': 'probability', 'topic': 'basic'}, {'id': 'prob_211', 'difficulty': 'intermediate', 'question': {'hy': 'Պարկում կա 3 կարմիր և 4 կանաչ գնդակ: Հանում ենք 2 գնդակ: Գտնել հանված կարմիր գնդակների քանակի մաթեմատիկական սպասումը:', 'en': 'A bag has 3 red and 4 green balls. Draw 2. Find the expected number of red balls drawn.', 'ru': 'В сумке 3 красных и 4 зеленых шара. Вынимают 2. Найти мат. ожидание числа красных шаров.'}, 'answer': '0.8571', 'related_theory_id': 'theory-rv-props', 'related_theory_hint': {'hy': 'Մաթեմատիկական սպասումը գծային է՝ անկախ նրանից գնդակները հանում ենք վերադարձով, թե առանց վերադարձի: E(X) = n * p, որտեղ p-ն մեկ գնդակի կարմիր լինելու հավանականությունն է:', 'en': 'Expectation is linear: E(X) = n * p, even without replacement. What is p for a single draw?', 'ru': 'Математическое ожидание линейно: E(X) = n * p, даже без возвращения. Чему равно p для одного шара?'}, 'related_theory_solution': {'hy': '1 գնդակի պարագայում կարմիր դուրս գալու հավանականությունը p = 3/7 է։ Քանի որ մաթեմատիկական սպասումը գծային հատկություն ունի (E(X+Y) = E(X) + E(Y)), ընկերություն չունի, որ գնդակները հանվում են առանց վերադարձի։ Երկու գնդակի (n=2) համար E(X) = 2 × (3/7) = 6/7 ≈ 0.8571։', 'en': 'By linearity of expectation, E(X) = n * P(Red on single draw) = 2 * (3/7) = 6/7 ≈ 0.8571.', 'ru': 'В силу линейности мат. ожидания, E(X) = n * P(красный при 1 извлечении) = 2 * (3/7) = 6/7 ≈ 0.8571.'}, 'track': 'probability', 'topic': 'random_variables'}, {'id': 'prob_310', 'difficulty': 'advanced', 'question': {'hy': 'Արդյունաբերական թափոնների 69%-ը հանքային են, 28%-ը՝ ոչ հանքային, 3%-ը՝ վտանգավոր։ Վերամշակվում է հանքայինի 73%-ը, ոչ հանքացինի 49%-ը և վտանգավորի 35%-ը։ Գտեք պատահական ընտրված թափոնի վերամշակվելու հավանականությունը:', 'en': '69% minerals (73% recycle), 28% non-minerals (49% recycle), 3% dangerous (35% recycle). Find total recycling probability.', 'ru': '69% минералы (73% переработка), 28% неминералы (49% переработка), 3% опасные (35% переработка). Найти общую вер. переработки.'}, 'answer': '0.6514', 'related_theory_id': 'theory-bayes', 'related_theory_hint': {'hy': 'Կիրառեք Լրիվ հավանականության բանաձևը։ Գումարեք յուրաքանչյուր խմբի հանդիպելու հավանականության և այդ խմբի վերամշակման հավանականության արտադրյալները:', 'en': 'Use the Law of Total Probability to find the weighted average of recycling rates.', 'ru': 'Используйте формулу полной вероятности (взвешенное среднее вероятностей).'}, 'related_theory_solution': {'hy': 'Ըստ լրիվ հավանականության բանաձևի՝ P = P(H)*P(V|H) + P(Ո)*P(V|Ո) + P(Վտ)*P(V|Վտ) = 0.69 × 0.73  +  0.28 × 0.49  +  0.03 × 0.35 = 0.5037 + 0.1372 + 0.0105 = 0.6514։', 'en': 'Law of Total Probability: P = (0.69 × 0.73) + (0.28 × 0.49) + (0.03 × 0.35) = 0.5037 + 0.1372 + 0.0105 = 0.6514.', 'ru': 'Формула полной вероятности: P = (0.69 × 0.73) + (0.28 × 0.49) + (0.03 × 0.35) = 0.5037 + 0.1372 + 0.0105 = 0.6514.'}, 'track': 'probability', 'topic': 'bayes'}, {'id': 'prob_410', 'difficulty': 'olympic', 'question': {'hy': 'Պատահական մեծության E(X)=100, Var(X)=25: Չեբիշևի անհավասարության օգնությամբ հաշվեք P(|X-100| ≥ 15) վերին սահմանը:', 'en': 'E(X)=100, Var(X)=25. Use Chebyshev to find upper bound for P(|X-100| ≥ 15).', 'ru': 'E(X)=100, Var(X)=25. Верхняя граница P(|X-100| ≥ 15) по Чебышёву?'}, 'answer': '0.1111', 'related_theory_id': 'theory-chebyshev', 'related_theory_hint': {'hy': 'Կիրառեք Չեբիշևի անհավասարությունը՝ P(|X - μ| ≥ k) ≤ Var(X) / k²։ Ուշադրություն դարձրեք, որ k = 15:', 'en': "Apply Chebyshev's inequality P(|X - μ| ≥ k) ≤ Var(X) / k² with k=15.", 'ru': 'Примените неравенство Чебышёва P(|X - μ| ≥ k) ≤ Var(X) / k² при k=15.'}, 'related_theory_solution': {'hy': 'Ըստ Չեբիշևի անհավասարության. P(|X - μ| ≥ k) ≤ Var(X) / k²։ Այստեղ E(X) = μ = 100, իսկ շեղումը k = 15 է։<br>P(|X - 100| ≥ 15) ≤ 25 / 15² = 25 / 225 = 1 / 9 ≈ 0.1111։', 'en': "Chebyshev's inequality: P(|X - μ| ≥ k) ≤ Var(X) / k². Here k = 15. So 25 / (15^2) = 25 / 225 = 1/9 ≈ 0.1111.", 'ru': 'Неравенство Чебышёва: P(|X - μ| ≥ k) ≤ Var(X) / k². Здесь k = 15. 25 / (15^2) = 25 / 225 = 1/9 ≈ 0.1111.'}, 'track': 'probability', 'topic': 'random_variables'}, {'id': 'prob_220', 'difficulty': 'intermediate', 'question': {'hy': 'Քանի՞ եղանակով կարելի է 10 հոգանոց խմբից ընտրել նախագահ և քարտուղար:', 'en': 'How many ways to choose a president and a secretary from a group of 10 people?', 'ru': 'Сколькими способами можно выбрать президента и секретаря из группы в 10 человек?'}, 'answer': '90', 'related_theory_id': 'theory-arrangements', 'related_theory_hint': {'hy': 'Քանի որ պաշտոնները տարբեր են, հերթականությունը կարևոր է: Կիրառեք կարգավորությունների (Arrangements) բանաձևը:', 'en': 'Since the roles are different, order matters. Use the Arrangements formula A(n,k).', 'ru': 'Так как роли разные, порядок важен. Используйте формулу размещений A(n,k).'}, 'related_theory_solution': {'hy': 'A(10, 2) = 10! / (10-2)! = 10 × 9 = 90:', 'en': 'A(10, 2) = 10! / (10-2)! = 10 × 9 = 90.', 'ru': 'A(10, 2) = 10! / (10-2)! = 10 × 9 = 90.'}, 'track': 'probability', 'topic': 'combinatorics'}, {'id': 'prob_320', 'difficulty': 'advanced', 'question': {'hy': '2 զառ նետելիս, որքա՞ն է հավանականությունը, որ գումարը 7 է, եթե հայտնի է, որ առաջին զառի վրա 4 է ընկել:', 'en': 'Roll 2 dice. Prob sum is 7 given first die is 4?', 'ru': '2 кубика. Вероятность суммы 7, если на первом выпало 4?'}, 'answer': '0.1667', 'related_theory_id': 'theory-conditional-prob', 'related_theory_hint': {'hy': 'Սա պայմանական հավանականություն է: Քանի որ առաջին զառի արդյունքը արդեն գիտենք, հաջորդ քայլի համար կա միայն 6 հնարավոր տարբերակ:', 'en': 'This is conditional probability. Since the first die is fixed, there are only 6 possibilities for the second die.', 'ru': 'Это условная вероятность. Так как первый кубик известен, для второго остается только 6 вариантов.'}, 'related_theory_solution': {'hy': 'Քանի որ առաջին զառը 4 է, միակ բարենպաստ ելքը երկրորդ զառի 3 լինելն է։ Քանի որ երկրորդ զառն ունի 6 ելք, հավանականությունը 1/6 ≈ 0.1667 է։', 'en': 'The first die is 4. The only favorable outcome is the second die being 3. Since the second die has 6 outcomes, P = 1/6 ≈ 0.1667.', 'ru': 'Первый кубик 4. Единственный благоприятный исход — 3 на втором кубике. Вероятность 1/6 ≈ 0.1667.'}, 'track': 'probability', 'topic': 'bayes'}, {'id': 'calc_101', 'track': 'integral', 'topic': 'derivative', 'difficulty': 'beginner', 'question': {'hy': 'Գտնել f(x) = x³ ֆունկցիայի ածանցյալի արժեքը x = 2 կետում:', 'en': 'Find the derivative of f(x) = x³ evaluated at x = 2.', 'ru': 'Найдите значение производной функции f(x) = x³ в точке x = 2.'}, 'answer': '12', 'related_theory_id': 'derivative-rules-formulas', 'related_theory_hint': {'hy': "Կիրառեք աստիճանի ածանցման կանոնը՝ (xⁿ)' = n·xⁿ⁻¹։", 'en': "Use the power rule: (xⁿ)' = n·xⁿ⁻¹.", 'ru': "Используйте правило степени: (xⁿ)' = n·xⁿ⁻¹."}, 'related_theory_solution': {'hy': "f'(x) = 3x²։ x = 2 դեպքում՝ f'(2) = 3·(2)² = 12։", 'en': "f'(x) = 3x². At x = 2: f'(2) = 3·(2)² = 12.", 'ru': "f'(x) = 3x². При x = 2: f'(2) = 3·(2)² = 12."}}, {'id': 'calc_102', 'track': 'integral', 'topic': 'integral', 'difficulty': 'beginner', 'question': {'hy': 'Հաշվել որոշյալ ինտեգրալը՝ ∫₀² 3x² dx:', 'en': 'Evaluate the definite integral: ∫₀² 3x² dx.', 'ru': 'Вычислите определенный интеграл: ∫₀² 3x² dx.'}, 'answer': '8', 'related_theory_id': 'newton-leibniz-solved-examples', 'related_theory_hint': {'hy': 'Նախնական ֆունկցիան F(x) = x³ է։ Կիրառեք Նյուտոն–Լայբնիցի բանաձևը՝ F(2) - F(0)։', 'en': 'Antiderivative is F(x) = x³. Apply Newton–Leibniz: F(2) - F(0).', 'ru': 'Первообразная F(x) = x³. По формуле Ньютона–Лейбница: F(2) - F(0).'}, 'related_theory_solution': {'hy': '∫₀² 3x² dx = [x³]₀² = 2³ - 0³ = 8։', 'en': '[x³]₀² = 2³ - 0³ = 8.', 'ru': '[x³]₀² = 2³ - 0³ = 8.'}}, {'id': 'calc_103', 'track': 'integral', 'topic': 'derivative', 'difficulty': 'beginner', 'question': {'hy': 'Գտնել f(x) = 5x² - 4x + 7 ֆունկցիայի ածանցյալի արժեքը x = 3 կետում:', 'en': 'Find the derivative of f(x) = 5x² - 4x + 7 evaluated at x = 3.', 'ru': 'Найдите значение производной f(x) = 5x² - 4x + 7 в точке x = 3.'}, 'answer': '26', 'related_theory_id': 'derivative-rules-formulas', 'related_theory_hint': {'hy': "Ածանցյալը՝ f'(x) = 10x - 4։ Տեղադրեք x = 3։", 'en': "Derivative: f'(x) = 10x - 4. Substitute x = 3.", 'ru': "Производная: f'(x) = 10x - 4. Подставьте x = 3."}, 'related_theory_solution': {'hy': "f'(x) = 10x - 4։ f'(3) = 10·3 - 4 = 26։", 'en': "f'(x) = 10x - 4. f'(3) = 30 - 4 = 26.", 'ru': "f'(x) = 10x - 4. f'(3) = 30 - 4 = 26."}}, {'id': 'calc_104', 'track': 'integral', 'topic': 'integral', 'difficulty': 'beginner', 'question': {'hy': 'Հաշվել որոշյալ ինտեգրալը՝ ∫₀¹ (4x³ + 2x) dx:', 'en': 'Evaluate the definite integral: ∫₀¹ (4x³ + 2x) dx.', 'ru': 'Вычислите определенный интеграл: ∫₀¹ (4x³ + 2x) dx.'}, 'answer': '2', 'related_theory_id': 'newton-leibniz-solved-examples', 'related_theory_hint': {'hy': 'Նախնականը F(x) = x⁴ + x² է։', 'en': 'Antiderivative is F(x) = x⁴ + x².', 'ru': 'Первообразная F(x) = x⁴ + x².'}, 'related_theory_solution': {'hy': '[x⁴ + x²]₀¹ = (1 + 1) - 0 = 2։', 'en': '[x⁴ + x²]₀¹ = (1 + 1) - 0 = 2.', 'ru': '[x⁴ + x²]₀¹ = (1 + 1) - 0 = 2.'}}, {'id': 'calc_105', 'track': 'integral', 'topic': 'area', 'difficulty': 'beginner', 'question': {'hy': 'Գտնել y = 3x ուղղի տակ ընկած մակերեսը [0, 4] հատվածում:', 'en': 'Find the area under the line y = 3x on the interval [0, 4].', 'ru': 'Найдите площадь под прямой y = 3x на отрезке [0, 4].'}, 'answer': '24', 'related_theory_id': 'area-under-curve-axis', 'related_theory_hint': {'hy': 'A = ∫₀⁴ 3x dx կամ ուղղանկյուն եռանկյան մակերեսը՝ (4 · 12) / 2։', 'en': 'A = ∫₀⁴ 3x dx or triangle area: (4 · 12) / 2.', 'ru': 'A = ∫₀⁴ 3x dx или площадь треугольника: (4 · 12) / 2.'}, 'related_theory_solution': {'hy': 'A = [3x²/2]₀⁴ = 3·16/2 = 24։', 'en': 'A = [3x²/2]₀⁴ = 3·16/2 = 24.', 'ru': 'A = [3x²/2]₀⁴ = 3·16/2 = 24.'}}, {'id': 'calc_106', 'track': 'integral', 'topic': 'kinematics', 'difficulty': 'beginner', 'question': {'hy': 'Մարմինը շարժվում է v(t) = 6t (մ/վ) արագությամբ: Գտնել նրա տեղաշարժը t = 0-ից t = 3 վրկ միջակայքում:', 'en': 'A body moves with velocity v(t) = 6t (m/s). Find its displacement from t = 0 to t = 3 s.', 'ru': 'Тело движется со скоростью v(t) = 6t (м/с). Найдите перемещение от t = 0 до t = 3 с.'}, 'answer': '27', 'related_theory_id': 'kinematics-velocity-acceleration', 'related_theory_hint': {'hy': 'Տեղաշարժը՝ Δs = ∫₀³ 6t dt։', 'en': 'Displacement: Δs = ∫₀³ 6t dt.', 'ru': 'Перемещение: Δs = ∫₀³ 6t dt.'}, 'related_theory_solution': {'hy': 'Δs = [3t²]₀³ = 3·9 = 27 մետր։', 'en': 'Δs = [3t²]₀³ = 3·9 = 27 meters.', 'ru': 'Δs = [3t²]₀³ = 3·9 = 27 метров.'}}, {'id': 'calc_201', 'track': 'integral', 'topic': 'integral', 'difficulty': 'intermediate', 'question': {'hy': 'Հաշվել որոշյալ ինտեգրալը՝ ∫₀^π sin(x) dx:', 'en': 'Evaluate the definite integral: ∫₀^π sin(x) dx.', 'ru': 'Вычислите определенный интеграл: ∫₀^π sin(x) dx.'}, 'answer': '2', 'related_theory_id': 'area-riemann-sums', 'related_theory_hint': {'hy': 'sin(x)-ի նախնականը -cos(x) է։ Կիրառեք [-cos(x)]₀^π։', 'en': 'Antiderivative of sin(x) is -cos(x). Apply [-cos(x)]₀^π.', 'ru': 'Первообразная sin(x) равна -cos(x). Примените [-cos(x)]₀^π.'}, 'related_theory_solution': {'hy': '[-cos(π)] - [-cos(0)] = -(-1) - (-1) = 1 + 1 = 2։', 'en': '[-cos(π)] - [-cos(0)] = -(-1) - (-1) = 2.', 'ru': '[-cos(π)] - [-cos(0)] = 1 + 1 = 2.'}}, {'id': 'calc_202', 'track': 'integral', 'topic': 'area', 'difficulty': 'intermediate', 'question': {'hy': 'Գտնել f(x) = x գրաֆիկի և x առանցքի միջև երկրաչափական մակերեսը [-1, 1] հատվածում:', 'en': 'Find the geometric area between f(x) = x and the x-axis on [-1, 1].', 'ru': 'Найдите геометрическую площадь между f(x) = x и осью Ox на отрезке [-1, 1].'}, 'answer': '1', 'related_theory_id': 'area-under-curve-axis', 'related_theory_hint': {'hy': 'Ուշադրություն․ երկրաչափական մակերեսը A = ∫₋₁¹ |x| dx է, ոչ թե նշանով ինտեգրալը (որը 0 է)։', 'en': 'Note: geometric area is A = ∫₋₁¹ |x| dx, not signed integral (which is 0).', 'ru': 'Внимание: геометрическая площадь A = ∫₋₁¹ |x| dx, а не знаковый интеграл (который равен 0).'}, 'related_theory_solution': {'hy': 'A = ∫₋₁⁰ (-x)dx + ∫₀¹ x dx = 0.5 + 0.5 = 1։', 'en': 'A = ∫₋₁⁰ (-x)dx + ∫₀¹ x dx = 0.5 + 0.5 = 1.', 'ru': 'A = ∫₋₁⁰ (-x)dx + ∫₀¹ x dx = 0.5 + 0.5 = 1.'}}, {'id': 'calc_203', 'track': 'integral', 'topic': 'kinematics', 'difficulty': 'intermediate', 'question': {'hy': 'Մարմնի արագությունը v(t) = t - 1 է: Գտնել նրա տեղաշարժը (displacement) [0, 2] ժամանակահատվածում:', 'en': 'Particle velocity is v(t) = t - 1. Find its displacement over [0, 2].', 'ru': 'Скорость тела v(t) = t - 1. Найдите перемещение (displacement) на отрезке времени [0, 2].'}, 'answer': '0', 'related_theory_id': 'motion-constant-variable-accel', 'related_theory_hint': {'hy': 'Տեղաշարժը տրվում է սովորական նշանով ինտեգրալով՝ Δs = ∫₀² v(t) dt։', 'en': 'Displacement is the standard signed integral: Δs = ∫₀² v(t) dt.', 'ru': 'Перемещение равно обычному интегралу: Δs = ∫₀² v(t) dt.'}, 'related_theory_solution': {'hy': 'Δs = [t²/2 - t]₀² = (4/2 - 2) - 0 = 2 - 2 = 0։', 'en': 'Δs = [t²/2 - t]₀² = 2 - 2 = 0.', 'ru': 'Δs = [t²/2 - t]₀² = 2 - 2 = 0.'}}, {'id': 'calc_204', 'track': 'integral', 'topic': 'kinematics', 'difficulty': 'intermediate', 'question': {'hy': 'Մարմնի արագությունը v(t) = t - 1 է: Գտնել նրա անցած ընդհանուր ճանապարհը (total distance) [0, 2] ժամանակահատվածում:', 'en': 'Particle velocity is v(t) = t - 1. Find total distance traveled over [0, 2].', 'ru': 'Скорость тела v(t) = t - 1. Найдите полный пройденный путь на отрезке времени [0, 2].'}, 'answer': '1', 'related_theory_id': 'motion-constant-variable-accel', 'related_theory_hint': {'hy': 'Անցած ճանապարհը մոդուլի ինտեգրալն է՝ L = ∫₀² |v(t)| dt = ∫₀¹ (1-t)dt + ∫₁² (t-1)dt։', 'en': 'Total distance is the integral of absolute velocity: L = ∫₀² |v(t)| dt.', 'ru': 'Пройденный путь — интеграл от модуля скорости: L = ∫₀² |v(t)| dt.'}, 'related_theory_solution': {'hy': 'L = [t - t²/2]₀¹ + [t²/2 - t]₁² = 0.5 + 0.5 = 1 մետր։', 'en': 'L = 0.5 + 0.5 = 1 meter.', 'ru': 'L = 0.5 + 0.5 = 1 метр.'}}, {'id': 'calc_205', 'track': 'integral', 'topic': 'area', 'difficulty': 'intermediate', 'question': {'hy': 'Գտնել y = 2x ուղղով և y = x² պարաբոլով սահմանափակված պատկերի մակերեսը (կլորացնել մինչև 4 տասնորդական կամ կոտորակով):', 'en': 'Find the area enclosed between y = 2x and y = x² (round to 4 decimals or enter fraction).', 'ru': 'Найдите площадь фигуры, ограниченной y = 2x и y = x² (округлите до 4 знаков или введите дробь).'}, 'answer': '1.3333', 'related_theory_id': 'area-between-two-curves', 'related_theory_hint': {'hy': 'Հատման կետերը՝ x² = 2x => x = 0 և x = 2։ A = ∫₀² (2x - x²)dx = [x² - x³/3]₀²։', 'en': 'Intersections: x = 0 and x = 2. A = ∫₀² (2x - x²)dx = 4 - 8/3 = 4/3 ≈ 1.3333.', 'ru': 'Точки пересечения: x = 0 и x = 2. A = ∫₀² (2x - x²)dx = 4/3 ≈ 1.3333.'}, 'related_theory_solution': {'hy': 'A = [x² - x³/3]₀² = 4 - 8/3 = 4/3 ≈ 1.3333։', 'en': 'A = 4 - 8/3 = 4/3 ≈ 1.3333.', 'ru': 'A = 4 - 8/3 = 4/3 ≈ 1.3333.'}}, {'id': 'calc_206', 'track': 'integral', 'topic': 'numerical', 'difficulty': 'intermediate', 'question': {'hy': 'Մոնտե Կառլոյի Hit-or-Miss փորձում [0, 1]×[0, 1] քառակուսում գեներացվել է N=1000 կետ: f(x)=x² կորի տակ ընկել է 330 կետ: Ինչի՞ է հավասար ինտեգրալի մոտավոր գնահատականը:', 'en': 'In a Monte Carlo Hit-or-Miss trial on [0, 1]×[0, 1] with N=1000 points, 330 points land under f(x)=x². What is the estimated integral?', 'ru': 'В методе Монте-Карло Hit-or-Miss на [0, 1]×[0, 1] с N=1000 точками 330 точек попали под f(x)=x². Чему равна оценка интеграла?'}, 'answer': '0.33', 'related_theory_id': 'monte-carlo-hit-or-miss', 'related_theory_hint': {'hy': 'Բանաձևը՝ I ≈ S_box · (N_in / N) = 1 · (330 / 1000)։', 'en': 'Formula: I ≈ S_box · (N_in / N) = 1 · (330 / 1000).', 'ru': 'Формула: I ≈ S_box · (N_in / N) = 1 · (330 / 1000).'}, 'related_theory_solution': {'hy': 'I ≈ 1 · (330 / 1000) = 0.33։', 'en': 'I ≈ 0.33.', 'ru': 'I ≈ 0.33.'}}, {'id': 'calc_207', 'track': 'integral', 'topic': 'numerical', 'difficulty': 'intermediate', 'question': {'hy': 'Մոտարկել ∫₀² x² dx ինտեգրալը սեղանների կանոնով (Trapezoidal Rule)՝ n = 2 հավասար ենթամիջակայքերով:', 'en': 'Approximate ∫₀² x² dx using the Trapezoidal Rule with n = 2 equal subintervals.', 'ru': 'Приближенно вычислите ∫₀² x² dx методом трапеций при n = 2 равных подотрезках.'}, 'answer': '3', 'related_theory_id': 'numerical-integration-basics', 'related_theory_hint': {'hy': 'Քայլը՝ h = (2-0)/2 = 1։ Կետերը՝ x₀=0, x₁=1, x₂=2։ T₂ = (h/2)·[f(0) + 2f(1) + f(2)]։', 'en': 'Step: h = 1. Points: 0, 1, 2. T₂ = (1/2)·[0 + 2(1) + 4] = 3.', 'ru': 'Шаг h = 1. Узлы: 0, 1, 2. T₂ = (1/2)·[0 + 2(1) + 4] = 3.'}, 'related_theory_solution': {'hy': 'T₂ = 0.5 · (0 + 2·1 + 4) = 0.5 · 6 = 3։', 'en': 'T₂ = 0.5 · (0 + 2 + 4) = 3.', 'ru': 'T₂ = 0.5 · (0 + 2 + 4) = 3.'}}, {'id': 'calc_208', 'track': 'integral', 'topic': 'integral', 'difficulty': 'intermediate', 'question': {'hy': 'Գտնել k հաստատունը, եթե հայտնի է, որ ∫ (6x² + k) dx = 2x³ + 5x + C:', 'en': 'Find constant k if ∫ (6x² + k) dx = 2x³ + 5x + C.', 'ru': 'Найдите константу k, если известно, что ∫ (6x² + k) dx = 2x³ + 5x + C.'}, 'answer': '5', 'related_theory_id': 'antiderivative-indefinite-integral', 'related_theory_hint': {'hy': "Ածանցեք աջ կողմը՝ (2x³ + 5x + C)' = 6x² + 5։ Համեմատեք ինտեգրալի տակ եղած արտահայտության հետ։", 'en': "Differentiate the right-hand side: (2x³ + 5x + C)' = 6x² + 5.", 'ru': "Дифференцируйте правую часть: (2x³ + 5x + C)' = 6x² + 5."}, 'related_theory_solution': {'hy': "(2x³ + 5x + C)' = 6x² + 5։ Հետևաբար k = 5։", 'en': "(2x³ + 5x + C)' = 6x² + 5 => k = 5.", 'ru': "(2x³ + 5x + C)' = 6x² + 5 => k = 5."}}, {'id': 'calc_301', 'track': 'integral', 'topic': 'area', 'difficulty': 'advanced', 'question': {'hy': 'Գտնել y = x² պարաբոլով և y = 4 ուղղով սահմանափակված պատկերի մակերեսը (կլորացնել մինչև 4 տասնորդական կամ կոտորակով):', 'en': 'Find the area bounded by the parabola y = x² and the line y = 4 (round to 4 decimals or enter fraction).', 'ru': 'Найдите площадь фигуры, ограниченной параболой y = x² и прямой y = 4 (округлите до 4 знаков или введите дробь).'}, 'answer': '10.6667', 'related_theory_id': 'area-between-two-curves', 'related_theory_hint': {'hy': 'Հատման կետերը՝ x = -2 և x = 2։ A = ∫₋₂² (4 - x²)dx = 2 ∫₀² (4 - x²)dx = 32/3 ≈ 10.6667։', 'en': 'Intersections: x = ±2. A = ∫₋₂² (4 - x²)dx = 32/3 ≈ 10.6667.', 'ru': 'Точки пересечения: x = ±2. A = ∫₋₂² (4 - x²)dx = 32/3 ≈ 10.6667.'}, 'related_theory_solution': {'hy': 'A = [4x - x³/3]₋₂² = 32/3 ≈ 10.6667։', 'en': 'A = 32/3 ≈ 10.6667.', 'ru': 'A = 32/3 ≈ 10.6667.'}}, {'id': 'calc_302', 'track': 'integral', 'topic': 'volume', 'difficulty': 'advanced', 'question': {'hy': 'y = x գծով, y = 0 ուղղով և x = 1 սահմանով պատկերը պտտվում է x առանցքի շուրջ: Գտնել առաջացած մարմնի ծավալը (կլորացնել մինչև 4 տասնորդական կամ գրել π/3):', 'en': 'The region under y = x on [0, 1] rotates about the x-axis. Find the volume of the solid (round to 4 decimals or enter π/3).', 'ru': 'Фигура под y = x на [0, 1] вращается вокруг оси Ox. Найдите объем тела (округлите до 4 знаков или введите π/3).'}, 'answer': '1.0472', 'related_theory_id': 'volume-slicing-disks', 'related_theory_hint': {'hy': 'Սկավառակների մեթոդ՝ V = π ∫₀¹ (x)² dx = π [x³/3]₀¹ = π/3 ≈ 1.0472։', 'en': 'Disk method: V = π ∫₀¹ x² dx = π/3 ≈ 1.0472.', 'ru': 'Метод дисков: V = π ∫₀¹ x² dx = π/3 ≈ 1.0472.'}, 'related_theory_solution': {'hy': 'V = π [x³/3]₀¹ = π/3 ≈ 1.0472։', 'en': 'V = π/3 ≈ 1.0472.', 'ru': 'V = π/3 ≈ 1.0472.'}}, {'id': 'calc_303', 'track': 'integral', 'topic': 'volume', 'difficulty': 'advanced', 'question': {'hy': 'y = √x և y = x կորերի միջև ընկած տիրույթը [0, 1] հատվածում պտտվում է x առանցքի շուրջ: Գտնել օղակների մեթոդով ստացված ծավալը (կլորացնել մինչև 4 տասնորդական կամ գրել π/6):', 'en': 'The region between y = √x and y = x on [0, 1] rotates about the x-axis. Find the volume (round to 4 decimals or enter π/6).', 'ru': 'Область между y = √x и y = x на [0, 1] вращается вокруг оси Ox. Найдите объем тела вращения (округлите до 4 знаков или π/6).'}, 'answer': '0.5236', 'related_theory_id': 'volume-slicing-disks', 'related_theory_hint': {'hy': 'Օղակների մեթոդ՝ V = π ∫₀¹ ((√x)² - (x)²)dx = π ∫₀¹ (x - x²)dx = π(1/2 - 1/3) = π/6 ≈ 0.5236։', 'en': 'Washer method: V = π ∫₀¹ (x - x²)dx = π(1/6) ≈ 0.5236.', 'ru': 'Метод шайб: V = π ∫₀¹ (x - x²)dx = π/6 ≈ 0.5236.'}, 'related_theory_solution': {'hy': 'V = π [x²/2 - x³/3]₀¹ = π(1/6) ≈ 0.5236։', 'en': 'V = π/6 ≈ 0.5236.', 'ru': 'V = π/6 ≈ 0.5236.'}}, {'id': 'calc_304', 'track': 'integral', 'topic': 'integral', 'difficulty': 'advanced', 'question': {'hy': 'Հաշվել որոշյալ ինտեգրալը փոփոխականի փոխարինմամբ՝ ∫₀¹ 2x · e^(x²) dx (կլորացնել մինչև 4 տասնորդական կամ գրել e-1):', 'en': 'Evaluate the integral by substitution: ∫₀¹ 2x · e^(x²) dx (round to 4 decimals or write e-1).', 'ru': 'Вычислите интеграл методом замены переменной: ∫₀¹ 2x · e^(x²) dx (округлите до 4 знаков или e-1).'}, 'answer': '1.7183', 'related_theory_id': 'antiderivative-indefinite-integral', 'related_theory_hint': {'hy': 'Տեղադրենք u = x², du = 2x dx: [e^u]₀¹ = e¹ - e⁰ = e - 1 ≈ 1.7183։', 'en': 'Substitute u = x², du = 2x dx: [e^u]₀¹ = e - 1 ≈ 1.7183.', 'ru': 'Замена u = x², du = 2x dx: [e^u]₀¹ = e - 1 ≈ 1.7183.'}, 'related_theory_solution': {'hy': '[e^(x²)]₀¹ = e - 1 ≈ 1.7183։', 'en': 'e - 1 ≈ 1.7183.', 'ru': 'e - 1 ≈ 1.7183.'}}, {'id': 'calc_305', 'track': 'integral', 'topic': 'volume', 'difficulty': 'advanced', 'question': {'hy': 'Հաշվել R = 1 շառավղով գնդի ծավալը (կլորացնել մինչև 4 տասնորդական կամ գրել 4π/3):', 'en': 'Calculate the volume of a sphere with radius R = 1 (round to 4 decimals or enter 4π/3).', 'ru': 'Вычислите объем шара радиуса R = 1 (округлите до 4 знаков или введите 4π/3).'}, 'answer': '4.1888', 'related_theory_id': 'volume-slicing-disks', 'related_theory_hint': {'hy': 'Գնդի ծավալի բանաձևը՝ V = (4/3)·π·R³: R = 1 դեպքում՝ (4/3)·3.14159... ≈ 4.1888։', 'en': 'Sphere volume formula: V = (4/3)·π·R³ = (4/3)·π ≈ 4.1888.', 'ru': 'Объем шара: V = (4/3)·π·R³ = 4π/3 ≈ 4.1888.'}, 'related_theory_solution': {'hy': 'V = (4/3)·π ≈ 4.1888։', 'en': 'V = (4/3)·π ≈ 4.1888.', 'ru': 'V = (4/3)·π ≈ 4.1888.'}}, {'id': 'calc_306', 'track': 'integral', 'topic': 'kinematics', 'difficulty': 'advanced', 'question': {'hy': 'Մարմնի դիրքը տրված է s(t) = t³ - 12t (մետր) բանաձևով: Գտնել ժամանակի այն դրական պահը (t > 0), երբ նրա ակնթարթային արագությունը հավասարվում է 0-ի:', 'en': 'Position is s(t) = t³ - 12t (meters). Find the positive time t > 0 when instantaneous velocity is 0.', 'ru': 'Положение тела s(t) = t³ - 12t (метры). Найдите момент времени t > 0, когда мгновенная скорость равна 0.'}, 'answer': '2', 'related_theory_id': 'kinematics-velocity-acceleration', 'related_theory_hint': {'hy': "Արագությունը դիրքի ածանցյալն է՝ v(t) = s'(t) = 3t² - 12: Լուծեք 3t² - 12 = 0 հավասարումը:", 'en': "Velocity is derivative of position: v(t) = s'(t) = 3t² - 12 = 0 => t = 2.", 'ru': "Скорость — производная пути: v(t) = s'(t) = 3t² - 12 = 0 => t = 2."}, 'related_theory_solution': {'hy': 'v(t) = 3t² - 12 = 0 => t² = 4 => t = 2 վայրկյան։', 'en': '3t² - 12 = 0 => t = 2 seconds.', 'ru': '3t² - 12 = 0 => t = 2 секунды.'}}, {'id': 'calc_401', 'track': 'integral', 'topic': 'integral', 'difficulty': 'olympic', 'question': {'hy': 'Հայտնի է, որ ∫₀¹ x² dx = 1/3: Ինչի՞ է հավասար ∫₁⁰ x² dx ինտեգրալի արժեքը:', 'en': 'Given that ∫₀¹ x² dx = 1/3, what is the value of ∫₁⁰ x² dx?', 'ru': 'Известно, что ∫₀¹ x² dx = 1/3. Чему равен интеграл ∫₁⁰ x² dx?'}, 'answer': '-0.3333', 'related_theory_id': 'area-riemann-sums', 'related_theory_hint': {'hy': 'Որոշյալ ինտեգրալի հիմնարար հատկությունը՝ սահմանները փոխելիս նշանը փոխվում է հակադարձի՝ ∫_b^a f(x)dx = -∫_a^b f(x)dx։', 'en': 'Fundamental property: reversing limits inverts sign: ∫_b^a f(x)dx = -∫_a^b f(x)dx.', 'ru': 'Свойство интеграла: перестановка пределов меняет знак: ∫_b^a f(x)dx = -∫_a^b f(x)dx.'}, 'related_theory_solution': {'hy': '∫₁⁰ x² dx = -∫₀¹ x² dx = -1/3 ≈ -0.3333։', 'en': '∫₁⁰ x² dx = -1/3 ≈ -0.3333.', 'ru': '∫₁⁰ x² dx = -1/3 ≈ -0.3333.'}}, {'id': 'calc_402', 'track': 'integral', 'topic': 'integral', 'difficulty': 'olympic', 'question': {'hy': 'Հաշվել որոշյալ ինտեգրալը մասերով ինտեգրման մեթոդով՝ ∫₀^π x · cos(x) dx:', 'en': 'Evaluate using integration by parts: ∫₀^π x · cos(x) dx.', 'ru': 'Вычислите методом интегрирования по частям: ∫₀^π x · cos(x) dx.'}, 'answer': '-2', 'related_theory_id': 'newton-leibniz-solved-examples', 'related_theory_hint': {'hy': 'Մասերով ինտեգրում՝ u = x, dv = cos(x)dx => du = dx, v = sin(x)։ ∫ u dv = uv - ∫ v du։', 'en': 'Integration by parts: u = x, dv = cos(x)dx => [x sin(x)]₀^π - ∫₀^π sin(x)dx = 0 - [-cos(x)]₀^π = -(1 - (-1)) = -2.', 'ru': 'Интегрирование по частям: u = x, dv = cos(x)dx => [x sin x]₀^π - ∫₀^π sin x dx = -2.'}, 'related_theory_solution': {'hy': '[x sin(x)]₀^π - [-cos(x)]₀^π = 0 - (1 - (-1)) = -2։', 'en': '[x sin(x)]₀^π - [-cos(x)]₀^π = -2.', 'ru': '[x sin(x)]₀^π - [-cos(x)]₀^π = -2.'}}, {'id': 'calc_403', 'track': 'integral', 'topic': 'volume', 'difficulty': 'olympic', 'question': {'hy': 'Մարմնի հիմքը x² + y² ≤ 1 շրջանն է: x առանցքին ուղղահայաց բոլոր լայնական հատույթները քառակուսիներ են: Գտնել մարմնի ծավալը (կլորացնել մինչև 4 տասնորդական կամ կոտորակով):', 'en': 'The base of a solid is the disk x² + y² ≤ 1. Cross-sections perpendicular to the x-axis are squares. Find the volume (round to 4 decimals or enter fraction).', 'ru': 'Основание тела — круг x² + y² ≤ 1. Сечения, перпендикулярные оси Ox — квадраты. Найдите объем тела (округлите до 4 знаков или дробь).'}, 'answer': '5.3333', 'related_theory_id': 'volume-slicing-disks', 'related_theory_hint': {'hy': 'Յուրաքանչյուր x-ում քառակուսու կողմը s = 2√(1 - x²) է: Հատույթի մակերեսը՝ A(x) = s² = 4(1 - x²): V = ∫₋₁¹ 4(1 - x²)dx = 16/3 ≈ 5.3333։', 'en': 'Side of square is s = 2√(1 - x²). Area A(x) = 4(1 - x²). V = ∫₋₁¹ 4(1 - x²)dx = 16/3 ≈ 5.3333.', 'ru': 'Сторона квадрата s = 2√(1 - x²). Площадь A(x) = 4(1 - x²). V = ∫₋₁¹ 4(1 - x²)dx = 16/3 ≈ 5.3333.'}, 'related_theory_solution': {'hy': 'V = ∫₋₁¹ 4(1 - x²)dx = 8 [x - x³/3]₀¹ = 8 · (2/3) = 16/3 ≈ 5.3333։', 'en': 'V = 16/3 ≈ 5.3333.', 'ru': 'V = 16/3 ≈ 5.3333.'}}]
